import{_ as l,a0 as i,w as m,s as a,ao as s,I as r,x as e,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse(`{"title":"Linux 的 ‘sort’命令的14个有用的范例（一） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 的 ‘sort’命令的14个有用的范例（一） | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 的 ‘sort’命令的14个有用的范例（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 的 ‘sort’命令的14个有用的范例（一） | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150417 14 Useful Examples of Linux 'sort' Command--Part 1","title":"Linux 的 ‘sort’命令的14个有用的范例（一）","tag":"201505","desc":""},"relativePath":"201505/20150417 14 Useful Examples of Linux 'sort' Command--Part 1.md","filePath":"[post].md"}`),d={name:"201505/20150417 14 Useful Examples of Linux 'sort' Command--Part 1.md"};function u(c,t,w,x,f,g){const o=i("Link");return m(),a("div",null,[t[16]||(t[16]=s(`<h1 id="linux-的-sort-命令的14个有用的范例-一" tabindex="-1">Linux 的 ‘sort’命令的14个有用的范例（一） <a class="header-anchor" href="#linux-的-sort-命令的14个有用的范例-一" aria-label="Permalink to “Linux 的 ‘sort’命令的14个有用的范例（一）”">​</a></h1><p>Sort是用于对单个或多个文本文件内容进行排序的Linux程序。Sort命令以空格作为字段分隔符，将一行分割为多个关键字对文件进行排序。需要注意的是除非你将输出重定向到文件中，否则Sort命令并不对文件内容进行实际的排序(即文件内容没有修改)，只是将文件内容按有序输出。</p><p>本文的目标是通过14个实际的范例让你更深刻的理解如何在Linux中使用sort命令。</p><p>1、 首先我们将会创建一个用于执行‘sort’命令的文本文件（tecmint.txt）。工作路径是‘/home/$USER/Desktop/tecmint’。</p><p>下面命令中的‘-e’选项将启用‘\\’转义，将‘\\n’解析成换行</p><pre><code>$ echo -e &quot;computer\\nmouse\\nLAPTOP\\ndata\\nRedHat\\nlaptop\\ndebian\\nlaptop&quot; &gt; tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Split-String-by-Lines.gif" alt="Split String by Lines in Linux"></p><p>2、 在开始学习‘sort’命令前，我们先看看文件的内容及其显示方式。</p><pre><code>$ cat tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-Content-of-File.gif" alt="Check Content of File"></p><p>3、 现在，使用如下命令对文件内容进行排序。</p><pre><code>$ sort tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content.gif" alt="Sort Content of File linux"></p><p><strong>注意</strong>：上面的命令并不对文件内容进行实际的排序，仅仅是将其内容按有序方式输出。</p>`,14)),r("p",null,[t[1]||(t[1]=e("4、 对文件‘tecmint.txt’文件内容排序，并将排序后的内容输出到名为sorted.txt的文件中，然后使用",-1)),n(o,{href:"http://www.tecmint.com/13-basic-cat-command-examples-in-linux/"},{default:p(()=>[...t[0]||(t[0]=[e("cat",-1)])]),_:1}),t[2]||(t[2]=e("命令查看验证sorted.txt文件的内容。",-1))]),t[17]||(t[17]=s(`<pre><code>$ sort tecmint.txt &gt; sorted.txt
$ cat sorted.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-File-Content.gif" alt="Sort File Content in Linux"></p><p>5、 现在使用‘-r’参数对‘tecmint.txt’文件内容进行逆序排序，并将输出内容重定向到‘reversesorted.txt’文件中，并使用cat命令查看文件的内容。</p><pre><code>$ sort -r tecmint.txt &gt; reversesorted.txt
$ cat reversesorted.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-By-Reverse.gif" alt="Sort Content By Reverse"></p><p>6、 创建一个新文件（lsl.txt），文件内容为在home目录下执行‘ls -l’命令的输出。</p><pre><code>$ ls -l /home/$USER &gt; /home/$USER/Desktop/tecmint/lsl.txt
$ cat lsl.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-Output.gif" alt="Populate Output of Home Directory"></p><p>我们将会看到对其他字段进行排序的例子，而不是对默认的开始字符进行排序。</p><p>7、 基于第二列（符号连接的数量）对文件‘lsl.txt’进行排序。</p><pre><code>$ sort -nk2 lsl.txt
</code></pre><p><strong>注意</strong>：上面例子中的‘-n’参数表示对数值内容进行排序。当想基于文件中的数值列对文件进行排序时，必须要使用‘-n’参数。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-by-Column.gif" alt="Sort Content by Column"></p><p>8、 基于第9列（文件和目录的名称，非数值）对文件‘lsl.txt’进行排序。</p><pre><code>$ sort -k9 lsl.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-Based-on-Column.gif" alt="Sort Content Based on Column"></p><p>9、 sort命令并非仅能对文件进行排序，我们还可以通过管道将命令的输出内容重定向到sort命令中。</p><pre><code>$ ls -l /home/$USER | sort -nk5
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-By-Pipeline.gif" alt="Sort Content Using Pipe Option"></p><p>10、 对文件tecmint.txt进行排序，并删除重复的行。然后检查重复的行是否已经删除了。</p><pre><code>$ cat tecmint.txt
$ sort -u tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-and-Remove-Duplicates.gif" alt="Sort and Remove Duplicates"></p><p>目前我们发现的排序规则：</p><p>除非指定了‘-r’参数，否则排序的优先级按下面规则排序</p><ul><li>以数字开头的行优先级最高</li><li>以小写字母开头的行优先级次之</li><li>待排序内容按字典序进行排序</li><li>默认情况下，‘sort’命令将带排序内容的每行关键字当作一个字符串进行字典序排序（数字优先级最高，参看规则 1）</li></ul><p>11、 在当前位置创建第三个文件‘lsla.txt’，其内容用‘ls -lA’命令的输出内容填充。</p><pre><code>$ ls -lA /home/$USER &gt; /home/$USER/Desktop/tecmint/lsla.txt
$ cat lsla.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-Output-With-Hidden-Files.gif" alt="Populate Output With Hidden Files"></p><p>了解ls命令的读者都知道‘ls -lA’ 等于 ‘ls -l’ + 隐藏文件，所以这两个文件的大部分内容都是相同的。</p><p>12、 对上面两个文件内容进行排序输出。</p><pre><code>$ sort lsl.txt lsla.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-of-Multiple-Files.gif" alt="Sort Contents of Two Files"></p><p>注意文件和目录的重复</p><p>13、 现在我们看看怎样对两个文件进行排序、合并，并且删除重复行。</p><pre><code>$ sort -u lsl.txt lsla.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Merge-Duplicates-Content.gif" alt="Sort, Merge and Remove Duplicates from File"></p><p>此时，我们注意到重复的行已经被删除了，我们可以将输出内容重定向到文件中。</p><p>14、 我们同样可以基于多列对文件内容进行排序。基于第2,5（数值）和9（非数值）列对‘ls -l’命令的输出进行排序。</p><pre><code>$ ls -l /home/$USER | sort -t &quot;,&quot; -nk2,5 -k9
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-By-Field-Column.gif" alt="Sort Content By Field Column"></p><p>先到此为止了，在接下来的文章中我们将会学习到‘sort’命令更多的详细例子。届时敬请关注我们。保持分享精神。若喜欢本文，敬请将本文分享给你的朋友。</p><hr>`,42)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),n(o,{href:"http://www.tecmint.com/sort-command-linux/"},{default:p(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/sort-command-linux/",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("作者：",-1)),n(o,{href:"http://www.tecmint.com/author/avishek/"},{default:p(()=>[...t[5]||(t[5]=[e("Avishek Kumar",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),n(o,{href:"https://github.com/cvsher"},{default:p(()=>[...t[6]||(t[6]=[e("cvsher",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:p(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const $=l(d,[["render",u]]);export{T as __pageData,$ as default};
